	// HasSeriesTimer applies the HasEdge predicate on the "series_timer" edge.
	func HasSeriesTimer() predicate.Timer {
		return predicate.Timer(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
				sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SeriesTimerTable,SeriesTimerColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
	}
	
	// HasSeriesTimerWith applies the HasEdge predicate on the "series_timer" edge with a given conditions (other predicates).
	func HasSeriesTimerWith(preds ...predicate.SeriesTimer) predicate.Timer {
		return predicate.Timer(func(s *sql.Selector) {
		step := newSeriesTimerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
	}


// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Timer) predicate.Timer {
	return predicate.Timer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Timer) predicate.Timer {
	return predicate.Timer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Timer) predicate.Timer {
	return predicate.Timer(sql.NotPredicates(p))
}





